static void mochTam(LinkedList<Objeto>L1,
                    LinkedList<Objeto>L2,
                    int max,int tam,int i){

    if(peso(L1)>max)return;

    if(!L1.isEmpty())
        System.out.println(L1);

    for(int k=i;k<L2.size();k++){

        Objeto x=L2.get(k);

        if(x.tam<=tam){
            L1.add(x);
            mochTam(L1,L2,max,tam,k+1);
            L1.removeLast();
        }
    }
}
